import{_ as t,o,c as a,a3 as n}from"./chunks/framework.DAK02U1-.js";const p=JSON.parse('{"title":"Command","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Command | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/clice/cli/command"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/clice/cli/command"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/cli/command"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/cli/command"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/cli/command"}]]},"headers":[],"relativePath":"clice/cli/command.md","filePath":"en/clice/cli/command.md","lastUpdated":1793393027000}'),i={name:"clice/cli/command.md"};function c(s,e,r,d,l,m){return o(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="command" tabindex="-1">Command <a class="header-anchor" href="#command" aria-label="Permalink to &quot;Command&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p><code>clice command</code> shows the commands clice compiles a file with, and converts compile commands into those, for other tools to read. It reads the compilation databases and asks the compilers they name; it needs neither an index nor a server.</p><p><strong>Usage</strong>: <code>clice command &lt;file&gt; [--workspace &lt;dir&gt;] [--configuration &lt;tag&gt;] [--json]</code></p><p><strong>Usage</strong>: <code>clice command convert &lt;compile_commands.json&gt; [--workspace &lt;dir&gt;] [--configuration &lt;tag&gt;]</code></p><p><strong>Usage</strong>: <code>clice command convert [--json] [--workspace &lt;dir&gt;] [--configuration &lt;tag&gt;] -- &lt;compiler&gt; &lt;arguments&gt;...</code></p><h2 id="a-file-s-commands" tabindex="-1">A file&#39;s commands <a class="header-anchor" href="#a-file-s-commands" aria-label="Permalink to &quot;A file&#39;s commands&quot;">​</a></h2><p><code>clice command &lt;file&gt;</code> lists every entry the compilation databases have for the file, in the order the build ranks them, the first being the one an editor compiles with until the user picks another. Each shows the database holding it, the entry as written, a <code>command</code> string split as clice splits it, and the command clice compiles the file with under that entry: the entry edited by the <a href="./../guide/configuration#rules">rules</a> of <code>clice.toml</code>, then resolved through the compiler it names, which gives the target and the system include directories as the arguments of a <code>-cc1</code> command. Where some of those directories hold files clice&#39;s compiles do not see — another compiler&#39;s builtin headers that clang&#39;s own stand in for (GCC&#39;s private ones, another clang&#39;s), and copies further down the list that compiler never reaches — a <code>hidden</code> line counts them for each (see <a href="./../design/command-resolve#toolchain-query">Toolchain Query</a>). When the compiler cannot be queried, because it is not installed or rejects the query, the error says why, and the command shown is the driver command clang&#39;s own driver reads in the compiler&#39;s place, as for a rule&#39;s <code>query_toolchain = false</code>: a tool built on a compatible Clang reads it as clice does. <code>--json</code> prints the same as one JSON object.</p><p>The databases are the ones the editor loads for the file: those the rules name, else the <code>compile_commands.json</code> at the project root, in its direct subdirectories and in the directories between the file and the root. A file without an entry of its own, such as a header, which the editor compiles under the command of a source including it, is reported as having none.</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ clice command src/main.cpp</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">/home/me/project/build/compile_commands.json:</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  directory: /home/me/project/build</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  command:   /usr/bin/g++ -std=c++20 -O2 -Werror -o main.o -c ../src/main.cpp</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  resolved:  /usr/bin/g++ -cc1 -main-file-name main.cpp -triple x86_64-unknown-linux-gnu -O2 … -internal-isystem /usr/include/c++/13 … -std=c++20 … -x c++ /home/me/project/src/main.cpp</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  hidden:    112 of the files in /usr/lib/gcc/x86_64-linux-gnu/13/include</span></span></code></pre></div><p>The exit code is 0 when the file&#39;s entries are listed, 1 when the file does not exist or no database lists it, 2 when the arguments do not parse.</p><h2 id="converting-commands" tabindex="-1">Converting commands <a class="header-anchor" href="#converting-commands" aria-label="Permalink to &quot;Converting commands&quot;">​</a></h2><p><code>clice command convert &lt;compile_commands.json&gt;</code>, or a directory holding one, prints the database with each entry&#39;s command, its <code>arguments</code> or <code>command</code>, replaced by the <code>arguments</code> clice compiles the entry&#39;s file with, edited by the rules of the project&#39;s <code>clice.toml</code>. The entry keeps its <code>file</code> and <code>output</code>; its <code>directory</code> is written absolute, a relative one taken from the database&#39;s directory; any other field is left out. An entry clice does not compile, such as an assembler source, keeps its command. A written command leaves out the directories of another compiler&#39;s builtin headers, whose hidden files it could not carry (see <a href="./../design/command-resolve#known-limitations">Known Limitations</a>). <code>clice command convert -- &lt;compiler&gt; &lt;arguments&gt;...</code> converts one command, which runs in the current directory and compiles one C-family source file, and prints it as a command line, or with <code>--json</code> as a database entry.</p><p>The converted commands are <code>-cc1</code> commands of the Clang clice is built on: they suit a tool built on a compatible Clang. A command whose compiler cannot be queried stays a driver command instead, the one clang&#39;s own driver reads in the compiler&#39;s place.</p><p>The exit code is 0 when every command is converted; 1 when a compiler cannot be queried, after printing what was converted, the commands it could not query as those driver commands; 1 as well when the database cannot be read or the command compiles no C-family source file or several; 2 when the arguments do not parse.</p>`,15)])])}const g=t(i,[["render",c]]);export{p as __pageData,g as default};
